arguments.command:
python3 -c '
import subprocess, time

code = """
const nameInput = document.querySelector("#project_name");
nameInput.value = "Apple - Website Design";
nameInput.dispatchEvent(new Event("input", {bubbles: true}));
nameInput.dispatchEvent(new Event("change", {bubbles: true}));

const identInput = document.querySelector("#project_identifier");
identInput.removeAttribute("readonly");
identInput.value = "apple-website-design";
identInput.dispatchEvent(new Event("input", {bubbles: true}));
identInput.dispatchEvent(new Event("change", {bubbles: true}));

const desc = "We are designing a new website for Apple and it needs to be live before Christmas. The goal is to increase conversion rates to help sell more iPhones this holiday season.";
const ck = document.querySelector(".ck-editor__editable")?.ckeditorInstance;
if (ck) {
    ck.setData(desc);
}
const descArea = document.querySelector("#project_description");
if (descArea) {
    descArea.value = desc;
}

const submitBtn = Array.from(document.querySelectorAll("button")).find(b => b.innerText.trim() === "Complete");
submitBtn.click();
"""
clean_code = " ".join(code.split())
subprocess.run(["xclip", "-selection", "clipboard"], input=clean_code.encode(), check=True)
subprocess.run(["xdotool", "key", "--clearmodifiers", "ctrl+v"], env={"DISPLAY": ":1"}, check=True)
subprocess.run(["xdotool", "key", "--clearmodifiers", "Return"], env={"DISPLAY": ":1"}, check=True)
'

