    subprocess.run(["xdotool", "mousemove", "150", "1012", "click", "1"], env={"DISPLAY": ":1"}, check=True)
    clean = " ".join(code.split())
    subprocess.run(["xclip", "-selection", "clipboard"], input=clean.encode(), check=True)
    subprocess.run(["xdotool", "key", "--clearmodifiers", "ctrl+v"], env={"DISPLAY": ":1"}, check=True)
    subprocess.run(["xdotool", "key", "--clearmodifiers", "Return"], env={"DISPLAY": ":1"}, check=True)

run_js("""
(async () => {
    const opts = [];
    for (let i = 1; i <= 10; i++) {
        try {
            const r = await fetch(`/api/v3/custom_options/${i}`);
            if (r.ok) {
                opts.push(await r.json());
            }
        } catch(e) {}
    }
    window._opts = opts;
})();
""")
time.sleep(1)

run_js("copy(JSON.stringify(window._opts));")
time.sleep(0.5)

out = subprocess.check_output(["xclip", "-o", "-selection", "clipboard"]).decode()
print("Custom options:", out)
'

